import { useState, useCallback, useEffect } from 'react'
import { Container, Loader } from '../../../../../../components'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import Tabs from '../../../../../../components/Tabs'
import { PKG_DETAILS_TAB_TRAVEL } from '../../../../Packages/constants'
import { PackageDetailsStyle } from './index.style'
import PackageConfirmDetails from '../../../../../../components/PackageConfirmDetail'
import PackageConfimation from '../../../../../../components/PackageConfirmationPage'
import PackageConfirmProtection from '../../../../../../components/PackageConfirmProtection'
import PackageConfirmInsured from '../../../../../../components/PackageConfirmInsured'
import { useHistory, useParams } from 'react-router'
import { useGetCustomerTravelDetails, useGetTravelDetails, useUpdateCustomerTravelCompleteDraft, useUpdateCustomerTravelDraft, useUpdateTravelCompleteDraft, useUpdateTravelDraft } from '../../../state/hooks/useTravelState'
import PolicyPaymentInfo from '../../../../../../components/TravelPaymentInfo'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import { TRAVEL_STEPS } from '../../../constant'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import PackageNotFound from '../../../../Packages/components/PackageNotFound'
import { useUpdateGlobal } from '../../../../../../state/globalState/hooks/useGlobalContext'
import ShareQuotation from '../../ShareQuotationTravel'

function ConfirmationPage () {
  const [activeTab, setActiveTab] = useState(PKG_DETAILS_TAB_TRAVEL[0])
  const history = useHistory()
  const [{ globalState: { isLoggedIn } = { } }] = useUpdateGlobal()
  const handleSelectedTab = useCallback((tab) => {
    // handle the tab selected
    setActiveTab(tab)
  }, [])
  const { id } = useParams()
  const [showShareSheet, setShowShareSheet] = useState(false)
  const [{ getTravelDetailsData = {} }, getTravelDetailsRequest] = useGetTravelDetails()
  const [, updateTravelDraftRequest] = useUpdateTravelDraft()
  const [, updateCustomerTravelDraftRequest] = useUpdateCustomerTravelDraft()
  const [{ getCompleteDraftData = {} }, updateCompleteDraftRequest] = useUpdateTravelCompleteDraft()
  const [ { getCustomerDraftQuoteDetailData = {} }, getCustomerDraftQuoteDetailRequest] = useGetCustomerTravelDetails()
  const [{
    GET_TRAVEL_DETAILS_ERROR,
    GET_CUSTOMER_DRAFT_QUOTE_DETAIL_ERROR,
    UPDATE_TRAVEL_DRAFT_ERROR,
    updateTravelDraftStatus,
    updateCustomerDraftQuoteStatus   
  }, dispatchError] = useErrorContextValue()
  const [{
    GET_COMPLETE_DRAFT_ERROR
    , getCompleteDraftStatus
  }, dispatchCompleteError] = useErrorContextValue()
  const [showPageLoader, setShowPageLoader] = useState(false)
  const [paymentReview, setPaymentReview] = useState(false)
  const [showPaymentButton, setShowPaymentButton] = useState(true)
  const [{ GET_TRAVEL_DETAILS_LOADER, UPDATE_TRAVEL_DRAFT_LOADER, COMPLETE_TRAVEL_DRAFT_LOADER, GET_CUSTOMER_DRAFT_QUOTE_DETAIL_LOADER }] = useLoaderContextValue()
  

  const handleSaveDraft = useCallback((getTravelDetailsData) => {
    const {
      id,
      policy_details: policyDetails = {}
    } = getTravelDetailsData
    const payloadData = {
      body: {
        section: 'mv_quote_summary',
        sub_section: 'mv_quote_summary',
        data: {
          section: undefined,
          sub_section: undefined,
          code: getTravelDetailsData.provider_package_code,
          ...policyDetails,
        }
      },
      draftQuoteId: id
    }
    if (isLoggedIn){
      updateTravelDraftRequest(payloadData)
    }
    else if (!isLoggedIn){
      updateCustomerTravelDraftRequest(payloadData)
    }
  }, [updateTravelDraftRequest, updateCustomerTravelDraftRequest, isLoggedIn])


  useEffect(() => {
    if (UPDATE_TRAVEL_DRAFT_ERROR && updateTravelDraftStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateTravelDraftStatus
      })
      dispatchError(resetError({
        updateTravelDraftStatus: ''
      }))
    }
  }, [UPDATE_TRAVEL_DRAFT_ERROR, updateTravelDraftStatus, dispatchError])

  const handleShowQuotationModal = () => {
    if (isLoggedIn) {
    setShowShareSheet(true)
    }
  }

  const completeDraftOnClick = () => {    
      if (getTravelDetailsData.status === 'completed') {
        if (getTravelDetailsData.policy_application_id) {
          history.push({
            pathname: `/payment/travel-insurance/${getTravelDetailsData.policy_application_id}`
          })
          return
        }
        ShowSnackbar.error({
          visible: true,
          text: ERROR_LANG.tryAfterSomeTime
        })
        return
      }
      const payloadDataForComplete = {
        id: getTravelDetailsData.id
      }
      updateCompleteDraftRequest(payloadDataForComplete)
  }

  const handleBackClick = () => {
    history.push({
      pathname: `/travel/registration/${id}`,
    });
  };

  useEffect(() => {
    if (GET_COMPLETE_DRAFT_ERROR && getCompleteDraftStatus) {
      setShowPageLoader(false)
      ShowSnackbar.error({
        visible: true,
        text: getCompleteDraftStatus
      })
      dispatchCompleteError(resetError({
        getCompleteDraftStatus: ''
      }))
    }
  }, [GET_COMPLETE_DRAFT_ERROR, getCompleteDraftStatus, dispatchCompleteError])

  useEffect(() => {
    if (getCompleteDraftStatus === 'success') {
      const { id } = getCompleteDraftData
      if (id) {
        history.push({
          pathname: `/payment/travel-insurance/${id}`
        })
      }
    }
  }, [getCompleteDraftStatus, history, getCompleteDraftData])

  useEffect(() => {
    if (isLoggedIn) {
      if (id) {
        getTravelDetailsRequest({ draftQuoteId: id })
      }
    }
    else {
        if (id) {
          getCustomerDraftQuoteDetailRequest({ draftQuoteId: id })
        }
    }
    }, [getTravelDetailsRequest, getCustomerDraftQuoteDetailRequest, isLoggedIn, id])

  useEffect(() => {
    if (isLoggedIn){
      if (getTravelDetailsData.id) {
        if (getTravelDetailsData.status === 'completed') {
          setShowPaymentButton(false)
          return
        }
        handleSaveDraft(getTravelDetailsData)
      }
    }
  }, [getTravelDetailsData, handleSaveDraft, isLoggedIn])

  useEffect(() => {
    if (updateTravelDraftStatus === 'success') {
      setShowPaymentButton(false)
    }
  }, [updateTravelDraftStatus, isLoggedIn])

  
  return (
    <Container
      title={LANG_STRINGS.confirmationData}
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      showInnerHeader
      displayBackButton
      hideBottomTabs
      className='bg-white'
      onBackClick={handleBackClick}
    >
      <PolicyStepsHeader
        stepsData={TRAVEL_STEPS}
        activeCount={4}
        prevActive={{
          1: true,
          2: true,
          3: true
        }}
      />
      <Loader visible={GET_TRAVEL_DETAILS_LOADER || UPDATE_TRAVEL_DRAFT_LOADER || COMPLETE_TRAVEL_DRAFT_LOADER || GET_CUSTOMER_DRAFT_QUOTE_DETAIL_LOADER || showPageLoader} />
      {
         GET_TRAVEL_DETAILS_ERROR || GET_CUSTOMER_DRAFT_QUOTE_DETAIL_ERROR
          ? (
            <PackageNotFound history={history} showProductBtn={false} />
          )
          : null
      } 
      <PackageDetailsStyle>
        <PackageConfimation getTravelDetailsData={isLoggedIn ? getTravelDetailsData : getCustomerDraftQuoteDetailData } />
        <Tabs
          data={PKG_DETAILS_TAB_TRAVEL}
          defaultTab={activeTab}
          onClick={handleSelectedTab}
          top='90px'
          borderBottom='#333333'
          isSticky
        />
        {
          activeTab.value === 'detail' && (
            <PackageConfirmDetails getTravelDetailsData={isLoggedIn ? getTravelDetailsData : getCustomerDraftQuoteDetailData } />
          )
        }
        {
          activeTab.value === 'protection' && (
            <PackageConfirmProtection getTravelDetailsData={isLoggedIn ? getTravelDetailsData : getCustomerDraftQuoteDetailData } />
          )
        }
        {
          activeTab.value === 'insured' && (
            <PackageConfirmInsured getTravelDetailsData={isLoggedIn ? getTravelDetailsData : getCustomerDraftQuoteDetailData } />
          )
        }
      </PackageDetailsStyle>
      { isLoggedIn &&
       <PolicyPaymentInfo
        policy={{
          basic_premium: getTravelDetailsData?.policy_details?.package_data?.basic_premium || getCustomerDraftQuoteDetailData?.policy_details?.package_data?.basic_premium,
          sub_total: getTravelDetailsData?.policy_details?.package_data?.basic_premium || getCustomerDraftQuoteDetailData?.policy_details?.package_data?.basic_premium,
          stamp_duty: getTravelDetailsData?.policy_details?.package_data?.stamp_duty || getCustomerDraftQuoteDetailData?.policy_details?.package_data?.stamp_duty,
          total_bill: getTravelDetailsData?.policy_details?.total_bill || getCustomerDraftQuoteDetailData?.policy_details?.total_bill,
          discount: getTravelDetailsData?.policy_details?.discount || getCustomerDraftQuoteDetailData?.policy_details?.discount,
          discount_percentage: getTravelDetailsData?.discount_percentage || getCustomerDraftQuoteDetailData?.policy_details?.discount_percentage,
          max_discount: getTravelDetailsData?.max_discount || getCustomerDraftQuoteDetailData?.policy_details?.max_discount
        }}
        btnText={LANG_STRINGS.payment}
        openButtonText={LANG_STRINGS.payment}
        onBuyClick={() => setPaymentReview(true)}
        onShareClick={handleShowQuotationModal}
        paymentReview={paymentReview}
        onCloseReview={() => setPaymentReview(false)}
        showDiscount
        onSaveDraft={completeDraftOnClick}
        isDisableButton={showPaymentButton}
        setShowPageLoader={setShowPageLoader}
        showDiscountCtn
        showDiscountAmount
      />
      }
      {
        showShareSheet && (
          <ShareQuotation
            show={showShareSheet}
            onClose={() => setShowShareSheet(false)}
          />
        )
      }
    </Container>

  )
}

export default ConfirmationPage
