import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useAddressFormStateValue } from '../../context'
import { getCityList, getProvinceList, validatePostalCode } from '../actions'
import { useCallback } from 'react'

export const useAddressFormServiceCall = (actionsCall = () => {}) => {
  const [addressState, dispatch] = useAddressFormStateValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [addressState, request]
}

export const useGetProvinceList = () => useAddressFormServiceCall(getProvinceList)

export const useGetCityList = () => useAddressFormServiceCall(getCityList)

export const useValidatePostalCode = () => useAddressFormServiceCall(validatePostalCode)
