import { MoreOptionsStyle } from './index.style'
import { LANG_STRINGS } from '../../lang/index'
import Heading from '../Heading/index'

function MoreOptions ({
  title, actions = [], gridColCount, onActionClick = () => {}
}) {
  return (
    <MoreOptionsStyle gridColCount={gridColCount}>
      <Heading
        title={title || LANG_STRINGS.moreOptions}
      />
      <div className='more-actions'>
        {
          actions.map(item => (
            <div
              key={item.type}
              onClick={() => onActionClick(item)}
              className='action'
            >
              <img src={item.icon} width='24px' alt={item.name} />
              <div className='action-name'>{item.name}</div>
            </div>
          ))
        }
      </div>
    </MoreOptionsStyle>
  )
}

export default MoreOptions
