import { useCallback, useState } from 'react'
import { TabsStyle, TabText } from './index.style'

function Tabs({
  data = [],
  defaultTab,
  onClick = () => {},
  isSticky,
  top,
  borderBottom,
  zIndex,
  fontSize,
}) {
  const [selectedTab, setSelectedTab] = useState(defaultTab || '')

  const handleTabSelect = useCallback(
    (tab) => {
      setSelectedTab(tab)
      onClick(tab)
    },
    [onClick]
  )

  return (
    <TabsStyle id="tabsContainer" isSticky={isSticky} top={top} zIndex={zIndex}>
      {data.map((tab, index) => {
        const isSelected = selectedTab.value === tab.value
        return (
          <TabText
            key={`tabs-${index}`}
            selected={isSelected}
            onClick={() => handleTabSelect(tab)}
            borderBottom={borderBottom}
            fontSize={fontSize}
            hasIcon={!!tab.icon}
          >
            {tab.icon && (
              <>
                <img src={tab.icon} width={24} height={24} alt="" />
                &nbsp;
              </>
            )}
            {(isSelected || !tab.icon) && tab.title}
          </TabText>
        )
      })}
    </TabsStyle>
  )
}

export default Tabs
