import { BackgroundGrey, ProfileContentStyle, ProfileItemStyle } from './index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import { CustomText } from '..'
import { Row } from '../../commonStyle/index.style'
import moment from 'moment'
import { capitalize } from 'lodash'

export const getProductDetails = (getTravelDetailsData) => [
  {
    name: 'Tipe Perjalanan',
    value: capitalize(getTravelDetailsData?.policy_details?.travel_type)
  },
  {
    name: 'Dari',
    value: getTravelDetailsData?.policy_details?.source
  },
  {
    name: 'Tujuan',
    value: (getTravelDetailsData?.policy_details?.destination).join(', ') || []
  }
]
export const getProductProtection = (getTravelDetailsData) => [
  {
    name: 'Awal Perlindungan',
    value: moment(getTravelDetailsData?.policy_details?.start_date).format(
      'DD/MM/YYYY'
    )
  },
  {
    name: 'Akhir Perlindungan',
    value: moment(getTravelDetailsData?.policy_details?.end_date).format(
      'DD/MM/YYYY'
    )
  },
  {
    name: 'Lama Perlindungan',
    value:
      getTravelDetailsData?.policy_details?.package_data?.applicable_period
  },
  {
    name: 'Jenis Perlindungan',
    value: capitalize(getTravelDetailsData?.policy_details?.policy_type)
  },
  {
    name: 'Jumlah Tertanggung',
    value: getTravelDetailsData?.policy_details?.package_data?.insured_count
  }
]

function PackageConfirmProtection ({getTravelDetailsData}) {

  const renderProfileCards = (list, title) => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          size='15px'
          bottom='10px'
          top='20px'
        >
          {title}
        </CustomText>
        <div className='bg-white profile-selection-container'>
          {list.map((item, index) => (
            <ProfileItemStyle
              border={index + 1 !== list.length}
              key={index}
              // onClick={() => handleProfilePage(item)}
            >
              <Row className='center-icon-text'>
                <CustomText
                  color={AgentColorPallette.fontGrey}
                  weight={400}
                  size='13px'
                  bottom='0'
                >
                  {item.name}
                </CustomText>
              </Row>
              <Row className='center-icon-text'>
                <CustomText
                  className='align-right'
                  color={AgentColorPallette.black}
                  weight={400}
                  size='13px'
                  bottom='0'
                >
                  {item.value}
                </CustomText>
              </Row>
              {/* <i className='fas fa-angle-right' /> */}
            </ProfileItemStyle>
          ))}
        </div>
      </>
    )
  }
  return (
    <BackgroundGrey>
      <ProfileContentStyle>
        {renderProfileCards(
          getProductDetails(getTravelDetailsData),
          'Detail Perjalanan'
        )}
        {renderProfileCards(
          getProductProtection(getTravelDetailsData),
          'Detail Proteksi'
        )}
      </ProfileContentStyle>
    </BackgroundGrey>
  )
}

export default PackageConfirmProtection
