import { useCallback, useEffect, useState } from 'react'
import { Error } from '../../../../commonStyle/index.style'
import FormItemLabel from '../FormItemLabel'
import { RadioV2Style } from './index.style'

function RadioV2({
  name,
  title,
  options = [], // [{ name, value, label, icon, additional_value }]
  defaultValue,
  disabled,
  error,
  variant = 'filled',
  onChange = () => {},
}) {
  const [selected, setSelected] = useState(defaultValue)

  useEffect(() => {
    if (!selected && defaultValue) {
      setSelected(defaultValue)
    }
  }, [selected, defaultValue])

  const handleSelect = useCallback(
    (item) => {
      if (disabled) return
      setSelected(item.value)
      onChange({ name, value: item.value }, item?.additional_value)
    },
    [onChange, name, disabled]
  )

  const renderRadioBox = useCallback(() => {
    return options.map((item) => (
      <div
        key={item.value}
        className={[
          'radio-box',
          selected === item.value ? 'selected' : '',
          disabled ? 'disabled' : '',
        ].join(' ')}
        onClick={() => handleSelect(item)}
      >
        {item.icon && (
          <div className={`icon-container icon-${item.iconSize || 'sm'}`}>
            <img src={item.icon} alt={item.label} />
          </div>
        )}
        <span>{item.label}</span>
      </div>
    ))
  }, [options, disabled, selected, handleSelect])

  return (
    <RadioV2Style error={error} variant={variant}>
      <FormItemLabel title={title} />
      <div className="radio-container">{renderRadioBox()}</div>
      {error && <Error>{error}</Error>}
    </RadioV2Style>
  )
}

export default RadioV2
