import { useState } from 'react'
import { BackgroundGrey, ProfileContentStyle, ProfileItemStyle } from './index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import { CustomText } from '..'
import { Row } from '../../commonStyle/index.style'
import moment from 'moment'
import { capitalize } from 'lodash'

export const getMainTraveller = (getTravelDetailsData) => [
  {
    name: getTravelDetailsData?.policy_details?.travel_type === 'domestic' ? (getTravelDetailsData?.customer_detail?.main_traveller?.citizenship === 'WNI' ? 'Nama Sesuai KTP' : 'Nama Sesuai KITAS/KITAP') : 'Nama Sesuai Passport',
    value: capitalize(getTravelDetailsData?.customer_detail?.main_traveller?.name)
  },
  ...(getTravelDetailsData?.policy_details?.travel_type === 'domestic' ? [{
    name: 'Kewarganegaraan',
    value: getTravelDetailsData?.customer_detail?.main_traveller?.citizenship
  }] : []),
  {
    name: getTravelDetailsData?.policy_details?.travel_type === 'domestic' ? (getTravelDetailsData?.customer_detail?.main_traveller?.citizenship === 'WNI' ? 'No. KTP' : 'No. KITAS/KITAP') : 'No. Paspor',
    value: getTravelDetailsData?.customer_detail?.main_traveller?.insured_id
  },
  {
    name: 'Jenis Kelamin',
    value: (getTravelDetailsData?.customer_detail?.main_traveller?.gender === 'male' ? 'Laki-laki' : 'Perempuan')
  },
  {
    name: getTravelDetailsData?.policy_details?.travel_type === 'domestic' ? (getTravelDetailsData?.customer_detail?.main_traveller?.citizenship === 'WNI' ? 'Alamat Sesuai KTP' : 'Alamat Domisili') : 'Alamat Domisili',
    value: getTravelDetailsData?.customer_detail?.main_traveller?.address
  },
  {
    name: 'Tanggal Lahir',
    value: moment(
      getTravelDetailsData?.customer_detail?.main_traveller?.date_of_birth
    ).format('DD/MM/YYYY')
  },
  {
    name: 'Ponsel',
    value: getTravelDetailsData?.customer_detail?.main_traveller?.mobile_no
  },
  {
    name: 'Email',
    value: getTravelDetailsData?.customer_detail?.main_traveller?.email
  }
]
