function PackageConfirmInsured ({ getTravelDetailsData }) {
  const [detailShow, setDetailShow] = useState(0)
  const toggleCollapse = (index) => {
    if (detailShow === index) {
      setDetailShow(null)
    } else {
      setDetailShow(index)
    }
  }

  const renderProfileCards = (list, title, index) => {
    return (
      <>
        <Row
          justify='space-between'
          align='center'
          onClick={() => toggleCollapse(index)}
        >
          <CustomText
            color={AgentColorPallette.black}
            weight={700}
            size='15px'
            bottom='10px'
            top='20px'
          >
            {title}
          </CustomText>
          <CustomText
            color={AgentColorPallette.regular}
            weight={700}
            size='15px'
            bottom='10px'
            top='20px'
          >
            <i
              className={`fas ${
                detailShow === index ? 'fa-angle-up' : 'fa-angle-down'
              }`}
            />
          </CustomText>
        </Row>
        {detailShow === index && (
          <div>
            <div className='bg-white profile-selection-container'>
              {list.map((item, index) => (
                <ProfileItemStyle
                  border={index + 1 !== list.length}
                  key={index}
                >
                  <Row className='center-icon-text'>
                    <CustomText
                      color={AgentColorPallette.fontGrey}
                      weight={400}
                      size='13px'
                      bottom='0'
                    >
                      {item.name}
                    </CustomText>
                  </Row>
                  <Row className='center-icon-text'>
                    <CustomText
                      className='align-right'
                      color={AgentColorPallette.black}
                      weight={400}
                      size='13px'
                      bottom='0'
                    >
                      {item.value}
                    </CustomText>
                  </Row>
                </ProfileItemStyle>
              ))}
            </div>
          </div>
        )}
      </>
    )
  }

  return (
    <BackgroundGrey>
      <ProfileContentStyle>
        {renderProfileCards(
          getMainTraveller(getTravelDetailsData),
          'Traveler Utama',
          0
        )}

        {/* {getTravelDetailsData?.customer_detail?.adults.length > 0 &&
          renderProfileCards(
            getPartnerDeatils(getTravelDetailsData),
            'Pasangan',
            1
          )} */}

        {getTravelDetailsData?.policy_details?.policy_type === 'family' &&
        getTravelDetailsData?.customer_detail?.adults.length > 0 &&
         (getTravelDetailsData?.customer_detail?.adults).map((item, index) => {
           return renderProfileCards(
             getPartnerDeatils(item, getTravelDetailsData?.policy_details?.travel_type),
              `Tertanggung Tambahan ${index + 1}`,
              index + 2
           )
         })}

        {getTravelDetailsData?.policy_details?.policy_type === 'group' &&
        getTravelDetailsData?.customer_detail?.adults.length > 0 &&
         (getTravelDetailsData?.customer_detail?.adults).map((item, index) => {
           return renderProfileCards(
             getGroupDetails(item, getTravelDetailsData?.policy_details?.travel_type),
              `Tertanggung Tambahan ${index + 1}`,
              index + 2
           )
         })}

        {getTravelDetailsData?.policy_details?.policy_type === 'family' &&
        getTravelDetailsData?.customer_detail?.kids.length > 0 &&
          (getTravelDetailsData?.customer_detail?.kids).map((item, index) => {
            return renderProfileCards(
              getChildData(item, getTravelDetailsData?.policy_details?.travel_type),
              `Anak  ${index + 1}`,
              index + 3
            )
          })}
      </ProfileContentStyle>
    </BackgroundGrey>
  )
}

export default PackageConfirmInsured
