import styled from 'styled-components'

export const RadioInputStyle = styled.div`
  margin-bottom: 1rem;

  .radio-items {
    margin-top: 0.4rem;
  }
`

export const RadioElementStyle = styled.div`
   /* The container */
   border-top: 1px solid ${props => props.noBorder ? '#FFFFFF' : props.theme.Gray90};
   padding: 1.125rem 0.4rem;
   background-color: ${props => props.disabled ? props.theme.fontLightGrey : 'transparent'};

  .radio-container {
    display: flex;
    align-items: center;
    position: relative;
    padding-left: 40px;
    cursor: pointer;
    font-size: ${props => props.titleSize || '1em'};
  }

  .radio-label-title {
    font-size: 0.85em;
    color: ${props => props.disabled ? props.theme.fontGrey : props.theme.blackGrey};
  }

  .radio-label-text {
    flex: 1;
  }

  /* Hide the browser's default radio button */
  .radio-container input {
    position: absolute;
    opacity: 0;
    cursor: pointer;
  }

  /* Create a custom radio button */
  .checkmark {
    position: absolute;
    top: ${props => props.isSubText ? '8px' : 0};
    left: 0;
    height: 20px;
    width: 20px;
    background-color: ${props => props.theme.white};
    border: 1px solid ${props => props.borderColor || props.theme.Gray90};
    border-radius: 50%;
  }

  /* On mouse-over, add a grey background color */
  /* When the radio button is checked, add a blue background */
  input:checked ~ .checkmark {
    background-color: ${props => props.theme.primary};
  }

  input:disabled ~ .checkmark {
    background-color: ${props => props.theme.fontGrey};
  }

  /* Create the indicator (the dot/circle - hidden when not checked) */
  .checkmark:after {
    content: "";
    position: absolute;
    display: none;
  }

  /* Show the indicator (dot/circle) when checked */
  input:checked ~ .checkmark:after {
    display: block;
  }

  /* Style the indicator (dot/circle) */
  .checkmark:after {
    top: 5px;
    left: 5px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: black;
  }
`
