import { ProfileContentStyle, ProfileItemStyle, BackgroundGrey } from './index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import { CustomText } from '..'
import { Row } from '../../commonStyle/index.style'
import { capitalize } from 'lodash'
import { useHistory, useParams } from 'react-router'

export const getDetailPackets = (draftQuoteId) => [
  {
    name: 'Daftar Manfaat',
    url: `/travel/package_detail/${draftQuoteId}`,
    activeTab: 0
  },
  {
    name: 'Cara Pengajuan Klaim',
    url: `/travel/package_detail/${draftQuoteId}`,
    activeTab: 1
  },
  {
    name: 'Syarat & Ketentuan',
    url: `/travel/package_detail/${draftQuoteId}`,
    activeTab: 2
  }
]

export const getProductDetails = (getTravelDetailsData) => [
  {
    name: 'Produk Asuransi',
    value:
      getTravelDetailsData?.policy_details?.package_data?.package?.product
        ?.name
  },
  {
    name: 'Paket Asuransi',
    value: getTravelDetailsData?.policy_details?.package_data?.package?.name
  },
  {
    name: 'Provider Asuransi',
    value: getTravelDetailsData?.policy_details?.package_data?.name
  },
  {
    name: 'Jenis Asuransi',
    value: capitalize(getTravelDetailsData?.policy_details?.policy_type)
  }
]

function PackageConfirmDetails ({getTravelDetailsData}) {
  const history = useHistory()
  const { id } = useParams()

  const renderProfileCards = (list, title) => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          size='15px'
          bottom='10px'
          top='20px'
        >
          {title}
        </CustomText>
        <div className='bg-white profile-selection-container'>
          {list.map((item, index) => (
            <ProfileItemStyle border={index + 1 !== list.length} key={index}>
              <Row className='center-icon-text'>
                <CustomText
                  color={AgentColorPallette.fontGrey}
                  weight={400}
                  size='13px'
                  bottom='0'
                >
                  {item.name}
                </CustomText>
              </Row>
              <Row className='center-icon-text'>
                <CustomText
                  className='align-right'
                  color={AgentColorPallette.black}
                  weight={400}
                  size='13px'
                  bottom='0'
                >
                  {item.value}
                </CustomText>
              </Row>
            </ProfileItemStyle>
          ))}
        </div>
      </>
    )
  }
  const renderPacketCards = (list, title) => {
    return (
      <>
        <CustomText
          color={AgentColorPallette.black}
          weight={700}
          size='15px'
          bottom='10px'
          top='20px'
        >
          {title}
        </CustomText>
        <div className='bg-white profile-selection-container'>
          {list.map((item, index) => (
            <ProfileItemStyle
              border={index + 1 !== list.length}
              key={index}
              onClick={() => {
                return history.push({
                  pathname: item.url,
                  state: {
                    activeTab: item.activeTab,
                    isRedirected: true,
                    showDiscountCtn: false
                  }
                })
              }}
            >
              <Row className='center-icon-text'>
                <CustomText
                  color={AgentColorPallette.blue}
                  weight={400}
                  size='13px'
                  bottom='0'
                >
                  {item.name}
                </CustomText>
              </Row>
              <i className='fas fa-arrow-right' />
            </ProfileItemStyle>
          ))}
        </div>
      </>
    )
  }
  return (
    <BackgroundGrey>
      <ProfileContentStyle>
        {renderProfileCards(
          getProductDetails(getTravelDetailsData),
          'Detail Asuransi'
        )}
        {renderPacketCards(getDetailPackets(id), 'Detail Paket')}
      </ProfileContentStyle>
    </BackgroundGrey>
  )
}

export default PackageConfirmDetails
