import { useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, CustomText } from '../../../components'
import DynamicForm from '../../../components/DynamicForm'
import BottomActionSheet from '../../BottomActionSheet'
import ShowSnackbar from '../../../components/ShowNotification'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { formatDate } from '../../../helpers/formatDate'
import { ERROR_LANG, LANG_STRINGS } from '../../../lang/index'
import { ICON_ENDORSEMENT } from '../../../images'
import { useCreateEndorsementReq, useGetEndorsementReqForm } from '../../../containers/Private/Policy/state/hooks/usePolicyState'
import { ContentContainer, IconContainer, FormWrapper } from '../container/index.style'

const ENDORSEMENT_FORM = ({ formState, vehicleData, endorsementReasonList, isSubmitting }) => [
  {
    type: 'inputV2',
    name: 'endorsement_changes',
    title: LANG_STRINGS.endorsementRequirements,
    required: true,
    disabled: isSubmitting,
    data: {
      textArea: true
    }
  },
  {
    type: 'datePickerV3',
    name: 'effective_date',
    title: LANG_STRINGS.effectiveDate,
    required: true,
    disabled: isSubmitting,
    data: {
      minDate: vehicleData.coverage_period_start,
      maxDate: vehicleData.coverage_period_end
    }
  },
  {
    type: 'autoSearchBottomSheetv2',
    name: 'endorsement_reason',
    title: LANG_STRINGS.endorsementReason,
    required: true,
    disabled: isSubmitting,
    data: {
      data: endorsementReasonList,
      displayKey: 'title',
      dataKey: 'value',
      showHeader: true,
      headerTitle: LANG_STRINGS.endorsementReason,
      hideSearchBar: true
    }
  },
  ...((formState.endorsement_reason?.value === 'Lainnya')
    ? [{
      type: 'inputV2',
      name: 'other_desc',
      title: LANG_STRINGS.othersReason,
      required: true,
      disabled: isSubmitting,
      data: {
        textArea: true
      }
    }] : [])
]

const mapFormStateToApi = (policyId, formState) => ({
  insurance: policyId,
  effective_date: formatDate(formState, 'YYYY-MM-DD'),
  endorsement_changes: formState.endorsement_changes,
  endorsement_reason: [formState.endorsement_reason.value],
  other_desc: formState.other_desc
})

function EndorsementForm ({ show, vehicleData, onClose, onClickBack, onEndorsementSuccess }) {
  const formRef = useRef()
  const [formState, setFormState] = useState({})
  const [isSubmitDisabled, setIsSubmitDisabled] = useState(true)

  const [{ getEndorsementReqFormData }, getEndorsementReqFormRequest] = useGetEndorsementReqForm()
  const [, createEndorsementReqRequest] = useCreateEndorsementReq()
  const [{ CREATE_ENDORSEMENT_REQ_LOADER }] = useLoaderContextValue()
  const [{ createEndorsementReqStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const isSubmitting = !!CREATE_ENDORSEMENT_REQ_LOADER
  const endorsementReasonList = useMemo(() => getEndorsementReqFormData?.endorsement_reason?.data, [getEndorsementReqFormData])

  useEffect(() => {
    getEndorsementReqFormRequest()
  }, [getEndorsementReqFormRequest])

  const handleChangeFormData = (newData) => {
    if (newData.endorsement_reason) {
      if (newData.endorsement_reason?.value !== 'Lainnya') newData.other_desc = null
    }

    setFormState({ ...formState, ...newData })
    if (formRef.current?.validateFormValues(false)) {
      setIsSubmitDisabled(false)
    } else {
      setIsSubmitDisabled(true)
    }
  }

  const handleClickSubmit = () => {
    if (!formRef.current?.validateFormValues()) return

    createEndorsementReqRequest({
      body: mapFormStateToApi(vehicleData?.reference_id, formState)
    })
  }

  useEffect(() => {
    if (!createEndorsementReqStatus) return
    if (createEndorsementReqStatus === 'success') {
      onEndorsementSuccess()
      resetError(['createEndorsementReqStatus'])
    } else {
      ShowSnackbar.error({ text: ERROR_LANG.generalErrorTryAgain })
    }
  }, [onEndorsementSuccess, resetError, createEndorsementReqStatus])

  return createPortal(
    <BottomActionSheet
      onCloseSheet={onClose}
      show={show}
      zIndex={5}
      showHeader
    >
      <ContentContainer>
        <IconContainer>
          <img src={ICON_ENDORSEMENT} alt='' />
        </IconContainer>
        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size='0.9em'
          weight={800}
          textAlign='center'
          marginBottom='8px'
        >
          {LANG_STRINGS.endorsementSubmission}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='0.8em'
          weight={600}
          textAlign='center'
          marginBottom='8px'
        >
          {LANG_STRINGS.endorsementCompleteForm}
        </CustomText>

        <FormWrapper>
          <DynamicForm
            ref={formRef}
            formName='chasis-number-input'
            form={ENDORSEMENT_FORM({
              formState,
              vehicleData,
              endorsementReasonList,
              isSubmitting
            })}
            onChange={handleChangeFormData}
          />
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size='0.8em'
            weight={600}
            textAlign='center'
            marginTop='8px'
          >
            {LANG_STRINGS.endorsementRemark}
          </CustomText>
        </FormWrapper>

        <Button
          variant='filled'
          disabled={isSubmitDisabled}
          handleClick={handleClickSubmit}
          style={{ marginBottom: 8 }}
        >
          {LANG_STRINGS.applyEndorsement}
        </Button>
        <Button
          variant='outlined'
          handleClick={onClickBack}
        >
          {LANG_STRINGS.return}
        </Button>
      </ContentContainer>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default EndorsementForm
