import BottomActionSheet from '../../../BottomActionSheet'
import { PaymentBottomSheetStyle } from './index.style'
import { LANG_STRINGS } from '../../../../lang/index'
import { CustomText } from '../../..'
import { forwardRef, useEffect } from 'react'
import PaymentBreakup from '../PaymentBreakup'

function PaymentBottomSheet (
  {
    show,
    onClose,
    paymentMap,
    showDiscount,
    maxDiscountPercent,
    maxDiscount,
    loader = false,
    onDiscountChange = () => {},
    policy: { total_bill: totalBill } = {},
    setDisableBtn = () => {},
    handleBuy = () => {},
    isRedirected = false,
    showDiscountCtn = true,
    showDiscountAmount = false
  },
  parentRef
) {
  useEffect(() => {
    if (show) {
      document.body.style.overflowY = 'hidden'
    }
    return () => {
      document.body.style.overflowY = 'auto'
    }
  }, [show])

  return (
    <PaymentBottomSheetStyle>
      <BottomActionSheet
        loader={loader}
        show={show}
        onCloseSheet={onClose}
        headerTextAlign='start'
        bottom='58px'
        title={
          <div className='payment-header'>
            <CustomText
              color='#333333'
              size='1em'
              weight={700}
              textAlign='center'
            >
              {LANG_STRINGS.transactionDetail}
            </CustomText>
          </div>
        }
        showHeader
      >
        <div className='payment-amount-container'>
          <PaymentBreakup
            paymentMap={paymentMap}
            showDiscount={showDiscount}
            maxDiscount={maxDiscount}
            maxDiscountPercent={maxDiscountPercent}
            onDiscountChange={onDiscountChange}
            totalBill={totalBill}
            ref={parentRef}
            setDisableBtn={setDisableBtn}
            handleBuy={handleBuy}
            isRedirected={isRedirected}
            showDiscountCtn={showDiscountCtn}
            showDiscountAmount={showDiscountAmount}
          />
        </div>
      </BottomActionSheet>
    </PaymentBottomSheetStyle>
  )
}

export default forwardRef(PaymentBottomSheet)
