import { ConfigUrl } from '../../../../configs/url'
import { getHeaderUploadFile } from '../../../../helpers/utility'

export const TRAVEL_ACTIONS = {
  GET_TRAVEL_REGION_REQUEST: 'GET_TRAVEL_REGION_REQUEST',
  GET_TRAVEL_REGION: 'GET_TRAVEL_REGION',

  CREATE_TRAVEL_DRAFT_REQUEST: 'CREATE_TRAVEL_DRAFT_REQUEST',
  CREATE_TRAVEL_DRAFT: 'CREATE_TRAVEL_DRAFT',

  UPDATE_TRAVEL_DRAFT_REQUEST: 'UPDATE_TRAVEL_DRAFT_REQUEST',
  UPDATE_TRAVEL_DRAFT: 'UPDATE_TRAVEL_DRAFT',

  UPDATE_TRAVEL_SAVE_DRAFT_REQUEST: 'UPDATE_TRAVEL_SAVE_DRAFT_REQUEST',
  UPDATE_TRAVEL_SAVE_DRAFT: 'UPDATE_TRAVEL_SAVE_DRAFT',

  GET_TRAVEL_DETAILS_REQUEST: 'GET_TRAVEL_DETAILS_REQUEST',
  GET_TRAVEL_DETAILS: 'GET_TRAVEL_DETAILS',

  GET_PACKAGES_REQUEST: 'GET_PACKAGES_REQUEST',
  GET_PACKAGES: 'GET_PACKAGES',

  GET_PACKAGES_DETAIL_REQUEST: 'GET_PACKAGES_DETAIL_REQUEST',
  GET_PACKAGES_DETAIL: 'GET_PACKAGES_DETAIL',

  GET_COMPLETE_DRAFT_REQUEST: 'GET_COMPLETE_DRAFT_REQUEST',
  GET_COMPLETE_DRAFT: 'GET_COMPLETE_DRAFT',

  GET_CUSTOMER_COMPLETE_DRAFT_REQUEST: 'GET_CUSTOMER_COMPLETE_DRAFT_REQUEST',
  GET_CUSTOMER_COMPLETE_DRAFT: 'GET_CUSTOMER_COMPLETE_DRAFT',

  UPDATE_CUSTOMER_DRAFT_QUOTE_REQUEST: 'UPDATE_CUSTOMER_DRAFT_QUOTE_REQUEST',
  UPDATE_CUSTOMER_DRAFT_QUOTE: 'UPDATE_CUSTOMER_DRAFT_QUOTE',

  SHARE_DRAFT_QUOTE_REQUEST: 'SHARE_DRAFT_QUOTE_REQUEST',
  SHARE_DRAFT_QUOTE: 'SHARE_DRAFT_QUOTE',

  GET_CUSTOMER_DRAFT_QUOTE_DETAIL_REQUEST: 'GET_CUSTOMER_DRAFT_QUOTE_DETAIL_REQUEST',
  GET_CUSTOMER_DRAFT_QUOTE_DETAIL: 'GET_CUSTOMER_DRAFT_QUOTE_DETAIL',

  GET_DOWNLOAD_TRAVEL_DRAFT_PDF_REQUEST: 'GET_DOWNLOAD_TRAVEL_DRAFT_PDF_REQUEST',
  GET_DOWNLOAD_TRAVEL_DRAFT_PDF: 'GET_DOWNLOAD_TRAVEL_DRAFT_PDF',

  UPLOAD_TRAVEL_PASSENGER_REQUEST: 'UPLOAD_TRAVEL_PASSENGER_REQUEST',
  UPLOAD_TRAVEL_PASSENGER: 'UPLOAD_TRAVEL_PASSENGER',

  getTravelRegion: (payload = {}) => ({
    type: TRAVEL_ACTIONS.GET_TRAVEL_REGION_REQUEST,
    payload: {
      query: payload,
      method: 'get',
      url: ConfigUrl.getTravelRegionApi,
    },
  }),

  createTravelDraft: (payload = {}) => ({
    type: TRAVEL_ACTIONS.CREATE_TRAVEL_DRAFT_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      body: payload,
      url: ConfigUrl.createTravelDraftApi,
    },
  }),

  updateTravelDraft: (payload = {}) => ({
    type: TRAVEL_ACTIONS.UPDATE_TRAVEL_DRAFT_REQUEST,
    payload: {
      method: 'POST',
      body: payload.body,
      url: ConfigUrl.draftPolicyUpdateApi(payload.draftQuoteId),
    },
  }),

  updateTravelSaveDraft: (payload = {}) => ({
    type: TRAVEL_ACTIONS.UPDATE_TRAVEL_SAVE_DRAFT_REQUEST,
    payload: {
      method: 'POST',
      body: payload.body,
      url: ConfigUrl.draftPolicyUpdateApi(payload.draftQuoteId),
    },
  }),

  updateCustomerTravelDraft: (payload = {}) => ({
    type: TRAVEL_ACTIONS.UPDATE_CUSTOMER_DRAFT_QUOTE_REQUEST,
    payload: {
      method: 'POST',
      body: payload.body,
      url: ConfigUrl.updateCustomerDraftApi(payload.draftQuoteId),
    },
  }),

  getTravelDetails: (payload) => ({
    type: TRAVEL_ACTIONS.GET_TRAVEL_DETAILS_REQUEST,
    payload: {
      method: 'GET',
      url: ConfigUrl.policyDraftDetailsApi(payload.draftQuoteId),
    },
  }),

  getCustomerTravelDetails: (payload) => ({
    type: TRAVEL_ACTIONS.GET_CUSTOMER_DRAFT_QUOTE_DETAIL_REQUEST,
    payload: {
      method: 'GET',
      url: ConfigUrl.customerQuoteDraftDetailsApi(payload.draftQuoteId),
    },
  }),

  shareDraftQuoteTravelToCustomerReq: (payload = {}) => ({
    type: TRAVEL_ACTIONS.SHARE_DRAFT_QUOTE_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.shareDraftQuoteApi,
      method: 'POST',
    },
  }),

  getPackagesList: (payload = {}) => ({
    type: TRAVEL_ACTIONS.GET_PACKAGES_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.getInsuredPackageListApi,
      method: 'POST',
    },
  }),

  getPackagesDetail: (payload = {}) => ({
    type: TRAVEL_ACTIONS.GET_PACKAGES_DETAIL_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.getInsuredPackageDetailApi(payload.body.package_code),
      method: 'POST',
    },
  }),

  updateTravelCompleteDraft: (payload = {}) => ({
    type: TRAVEL_ACTIONS.GET_COMPLETE_DRAFT_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.getTravelCompleteDraftApi(payload.id),
      method: 'POST',
    },
  }),

  updateCustomerTravelCompleteDraft: (payload = {}) => ({
    type: TRAVEL_ACTIONS.GET_CUSTOMER_COMPLETE_DRAFT_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.completeCustomerDraftApi(payload.id),
      method: 'POST',
    },
  }),

  getTravelDraftDownloadPdfReq: (payload) => ({
    type: TRAVEL_ACTIONS.GET_DOWNLOAD_TRAVEL_DRAFT_PDF_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.downloadDraftPdfApi(payload.draftQuoteId),
      method: 'GET',
    },
  }),

  uploadTravelPassenger: (payload) => ({
    type: TRAVEL_ACTIONS.UPLOAD_TRAVEL_PASSENGER_REQUEST,
    payload: {
      ...payload,
      url: ConfigUrl.uploadTravelPassengerApi(payload.draftQuoteId),
      method: 'POST',
      headers: {
        ...getHeaderUploadFile(),
      },
    },
  }),
}
